        event.preventDefault();
        main.scrollIntoView({ block: 'start' });
        main.focus({ preventScroll: true });
      });
      skipLink.addEventListener('keydown', function (event) {
        if (event.key === 'Enter' || event.key === ' ') {
          event.preventDefault();
          main.scrollIntoView({ block: 'start' });
          main.focus({ preventScroll: true });
        }
      });
    }
